QUESTION_BANK_CHUNKS["law_判断"]={"id":"law_判断","name":"建设工程安全生产法律法规—判断","questionCount":380,"type":"judge","questions":[{"id":1,"type":"judge","stem":"生产经营单位主要负责人的安全生产工作职责有制止和纠正违章指挥、强令冒险作业、违反操作规程的行为。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_1"},{"id":2,"type":"judge","stem":"生产经营单位主要负责人组织制定并实施本单位安全生产规章制度和操作规程。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_2"},{"id":3,"type":"judge","stem":"《生产安全事故应急条例》规定，生产经营单位应当加强生产安全事故应急工作，建立、健全生产安全事故应急工作责任制，安全负责人对本单位的生产安全事故应急工作全面负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_3"},{"id":4,"type":"judge","stem":"当企业发生生产安全事故时，企业负责人应当迅速组织抢救，减少人员伤亡和财产损失。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_4"},{"id":5,"type":"judge","stem":"健全本单位安全生产责任制，组织制定并实施本单位安全生产教育和培训计划是单位主要负责人的安全职责。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_5"},{"id":6,"type":"judge","stem":"生产经营单位的安全生产管理人员组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_6"},{"id":7,"type":"judge","stem":"生产经营单位的安全生产管理人员负责健全本单位安全生产责任制，并实施本单位安全生产教育和培训计划。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_7"},{"id":8,"type":"judge","stem":"组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况是生产经营单位安全生产管理人员的职责。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_8"},{"id":9,"type":"judge","stem":"生产经营单位的安全生产管理人员负责督促落实本单位重大危险源的安全管理措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_9"},{"id":10,"type":"judge","stem":"组织或参与拟定本单位安全生产规章制度、操作规程是生产经营单位安全生产管理人员的职责。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_10"},{"id":11,"type":"judge","stem":"根据《房屋市政工程生产安全重大事故隐患判定标准》，本标准所称重大事故隐患，是指在房屋建筑和市政基础设施工程施工过程中，存在的危害程度较大、可能导致人员伤亡或造成重大经济损失的生产安全事故隐患。  （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_11"},{"id":12,"type":"judge","stem":"建筑施工特种作业人员未取得特种作业人员操作资格证书上岗作业属于一般事故隐患。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_12"},{"id":13,"type":"judge","stem":"申请人可以向户籍所在地或者就业所在地的考核发证机关报名参加建筑施工特种作业人员操作资格考核。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_13"},{"id":14,"type":"judge","stem":"特种作业资格证书不可以在全国通用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_14"},{"id":15,"type":"judge","stem":"建筑施工特种作业操作资格考核包括技术理论和操作技能两门科目。技术理论考核通过后，方可参加操作技能考核。两门科目均考核通过的，为考核合格。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_15"},{"id":16,"type":"judge","stem":"首次取得资格证书的建筑施工特种作业人员在正式上岗前，用人单位应当安排不少于6个月的实习操作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_16"},{"id":17,"type":"judge","stem":"资格证书不得伪造、涂改，不得倒卖、出租、出借或者以其他形式非法转让。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_17"},{"id":18,"type":"judge","stem":"任何单位和个人不得强迫、指使、纵容建筑施工特种作业人员违反建筑施工安全生产法律法规、强制性标准、操作规则进行作业。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_18"},{"id":19,"type":"judge","stem":"特级、一级施工总承包资质序列企业和一级专业承包资质序列企业宜设置专职安全总监。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_19"},{"id":20,"type":"judge","stem":"第八条 企业安全总监应当通过安全生产知识及管理能力的考核，具备中级及以上注册安全工程师执业资格，取得建筑施工企业主要负责人安全生产考核合格证书，且在本行业领域内从事安全管理工作满3年。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_20"},{"id":21,"type":"judge","stem":"企业主要负责人应当根据项目进度，带班检查企业在建项目的安全生产工作，每年检查时间不少于企业全年施工时间的25%，相关检查记录分别在企业和项目存档备查。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_21"},{"id":22,"type":"judge","stem":"建筑施工总承包特级资质企业安全生产管理机构专职安全生产管理人员配备应不少于5人。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_22"},{"id":23,"type":"judge","stem":"企业主要负责人应当熟悉房屋市政工程生产安全重大事故隐患判定标准，每月对企业重大事故隐患排查整改情况至少开展1次专项检查。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_23"},{"id":24,"type":"judge","stem":"房屋建筑工程施工面积大于10万平方米的，应当配备项目安全总监。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_24"},{"id":25,"type":"judge","stem":"项目安全总监应当具备注册安全工程师执业资格(建筑施工安全类)，取得建筑施工企业项目负责人安全生产考核合格证书，且在本行业领域内从事安全管理工作满5年。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_25"},{"id":26,"type":"judge","stem":"项目经理、项目安全总监均应当落实带班生产制度，每月带班生产时间不得少于本月施工时间的80%。因其他事务需短期离开施工现场时，应当书面委托项目相关负责人负责其外出时的安全生产工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_26"},{"id":27,"type":"judge","stem":"5万平方米以上的建筑工程项目不少于3人，且每增加5万平方米，应当至少增加1名专职安全生产管理人员。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_27"},{"id":28,"type":"judge","stem":"工程项目首次开展安全生产标准化考评工作的时间为办理监督手续当月起。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_28"},{"id":29,"type":"judge","stem":"工程项目安全生产标准化自评资料不符合要求，或与实际状况不符的，项目考评主体可书面说明理由并退回资料。（ ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_29"},{"id":30,"type":"judge","stem":"经安全生产标准化考评合格或优良的建筑施工企业及项目，发现有提交的材料弄虚作假的，由考评主体撤销原安全生产标准化考评结果，直接评定为不合格（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_30"},{"id":31,"type":"judge","stem":"经安全生产标准化考评合格或优良的建筑施工企业及项目，发现有漏报、谎报、瞒报生产安全事故的，由考评主体撤销原安全生产标准化考评结果，直接评定为不合格（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_31"},{"id":32,"type":"judge","stem":"省级考评主体负责全省特级、一级(含专业承包一级)、中央在陕建筑施工企业和所监管工程项目的安全生产标准化考评工作。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_32"},{"id":33,"type":"judge","stem":"建筑施工企业和作业人员在施工过程中，应当遵守有关安全生产的法律法规和建筑行业安全规章、规程，不得违章指挥或者违章作业。    （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_33"},{"id":34,"type":"judge","stem":"建筑施工项目经理必须按规定取得相应执业资格和安全生产考核合格证书。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_34"},{"id":35,"type":"judge","stem":"建筑施工项目经理可以同时在两个及两个以上的工程项目担任项目经理。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_35"},{"id":36,"type":"judge","stem":"建筑施工项目经理负责建立质量安全管理体系，负责配备专职质量、安全等施工现场管理人员。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_36"},{"id":37,"type":"judge","stem":"进入现场的建筑材料、构配件、设备、预拌混凝土，可先投入使用后再进行检测。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_37"},{"id":38,"type":"judge","stem":"建筑工程项目经理可以不参加单位工程和工程竣工验收，只需随后补齐签字手续即可。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_38"},{"id":39,"type":"judge","stem":"危险性较大分部分项工程施工期间项目经理无需现场带班。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_39"},{"id":40,"type":"judge","stem":"建筑工程施工资金周转困难时，项目经理可以先使用安全生产费用作为日常支出。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_40"},{"id":41,"type":"judge","stem":"安全生产责任保险，是指保险机构对投保的生产经营单位发生的生产安全事故造成的人员伤亡和有关经济损失等予以赔偿，并且为投保的生产经营单位提供事故预防服务的商业保险。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_41"},{"id":42,"type":"judge","stem":"对生产经营单位已投保的与安全生产相关的其他险种，应当增加或将其调整为安全生产责任保险，增强事故预防功能。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_42"},{"id":43,"type":"judge","stem":"除被依法关闭取缔、完全停止生产经营活动外，应当投保安全生产责任保险的生产经营单位不得延迟续保、退保。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_43"},{"id":44,"type":"judge","stem":"安全生产责任保险费率调整根据生产经营单位是否发生事故、事故次数和等级确定，可以根据发生人员伤亡的一般事故、较大事故、重大及以上事故次数进行调整。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_44"},{"id":45,"type":"judge","stem":"安全生产责任保险机构应当建立生产安全事故预防服务制度，协助投保的生产经营单位开展生产安全事故隐患排查工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_45"},{"id":46,"type":"judge","stem":"对拒不整改重大事故隐患的生产经营单位，下一投保年度保险机构不能上浮保险费率。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_46"},{"id":47,"type":"judge","stem":"同一生产经营单位的从业人员获取的保险金额，按照用工方式、工作岗位等进行不同对待。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_47"},{"id":48,"type":"judge","stem":"各地区应当在安全生产相关财政资金投入、信贷融资、项目立项、进入工业园区以及相关产业扶持政策等方面，在同等条件下优先考虑投保安全生产责任保险的生产经营单位。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_48"},{"id":49,"type":"judge","stem":"建筑施工安责险保险期限为企业购买工程项目安全责任保险之日至工程项目竣工验收备案之日。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_49"},{"id":50,"type":"judge","stem":"建筑施工安责险承保机构应在投保单位报案后2小时内到达事故现场。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_50"},{"id":51,"type":"judge","stem":"县级以上地方人民政府住房和城乡建设主管部门在其职责范围内具体负责本行政区域内建筑工程施工发包与承包违法行为的认定查处工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_51"},{"id":52,"type":"judge","stem":"承包单位将其承包的全部工程肢解以后，以分包的名义分别转给其他单位或个人施工的属于非法转包。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_52"},{"id":53,"type":"judge","stem":"挂靠是指单位或个人以其他有资质的施工单位的名义承揽工程的行为。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_53"},{"id":54,"type":"judge","stem":"违法发包是指承包单位承包工程后违反法律法规规定，把单位工程或分部分项工程分包给其他单位或个人施工的行为。 （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_54"},{"id":55,"type":"judge","stem":"建设主管部门在审核发放施工许可证时，对未取得安全生产许可证及安全生产许可证处于暂扣期内的，不得颁发施工许可证。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_55"},{"id":56,"type":"judge","stem":"建设工程实行施工总承包，总承包企业不得将工程分包给不具有安全生产许可证的专业承包企业或劳务分包企业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_56"},{"id":57,"type":"judge","stem":"建筑施工企业在12个月内第二次发生生产安全事故的，发生一般事故的，暂扣时限为在上一次暂扣时限的基础上再增加30日。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_57"},{"id":58,"type":"judge","stem":"12个月内同一企业连续发生三次生产安全事故的，吊销其安全生产许可证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_58"},{"id":59,"type":"judge","stem":"建筑施工企业在安全生产许可证暂扣期内，拒不整改的，吊销其安全生产许可证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_59"},{"id":60,"type":"judge","stem":"省级应急管理部门指导全省安全培训工作，依法对全省安全培训工作实施综合监督管理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_60"},{"id":61,"type":"judge","stem":"市级和县级应急管理部门按照各自职责，依法对生产经营单位安全培训工作实施监督管理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_61"},{"id":62,"type":"judge","stem":"具备安全培训条件的生产经营单位，应当以自主培训为主，不具备安全培训条件的生产经营单位，应当委托具备安全培训条件的机构，对从业人员进行安全培训，保证安全培训的责任仍由本单位负责（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_62"},{"id":63,"type":"judge","stem":"建筑施工特种作业人员应当在房屋市政工程范围内或者按照有关规定，按照其资格证书载明的工种从事相应的建筑施工特种作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_63"},{"id":64,"type":"judge","stem":"中央企业的分公司、子公司及其所属单位和其他生产经营单位，发生造成人员死亡的生产安全事故的，其主要负责人和安全生产管理人员应当重新参加安全培训（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_64"},{"id":65,"type":"judge","stem":"生产经营单位从业人员，是指生产经营单位主要负责人、安全生产管理人员、特种作业人员和其他从业人员。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_65"},{"id":66,"type":"judge","stem":"建设单位在进行项目可行性研究论证中，应当对建设项目的安全条件进行论证。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_66"},{"id":67,"type":"judge","stem":"建设项目安全设施初步设计未经安全生产监督管理部门审核同意的，不得开工建设。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_67"},{"id":68,"type":"judge","stem":"施工单位应当建立健全安全生产责任制度和安全生产教育培训制度，制定安全生产规章制度和操作规程，保证本单位安全生产条件所需资金的投入，对所承担的建设工程进行定期和专项安全检查，并做好安全检查记录。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_68"},{"id":69,"type":"judge","stem":"建设单位违反规定，安全生产设施未与主体工程同时设计、同时施工、同时投入生产和使用的，逾期未改正的，责令停产停业整顿，并处2万元以上10万元以下的罚款。  （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_69"},{"id":70,"type":"judge","stem":"施工单位对列入建设工程概算的安全作业环境及安全施工措施所需费用，可以挪作他用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_70"},{"id":71,"type":"judge","stem":"施工单位视情况决定是否设立安全生产管理机构，配备专职安全生产管理人员。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_71"},{"id":72,"type":"judge","stem":"项目经理负责对安全生产进行现场监督检查。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_72"},{"id":73,"type":"judge","stem":"施工单位可自行决定塔式起重机司机及信号工配备人数。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_73"},{"id":74,"type":"judge","stem":"建设工程实行施工总承包的，由监理单位对施工现场的安全生产负总责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_74"},{"id":75,"type":"judge","stem":"施工单位应当根据不同施工阶段和周围环境及季节、气候的变化，在施工现场采取相应的安全施工措施。   （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_75"},{"id":76,"type":"judge","stem":"施工单位不得在尚未竣工的建筑物内设置员工集体宿舍。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_76"},{"id":77,"type":"judge","stem":"施工现场临时搭建的建筑物应当符合安全使用要求。施工现场使用的装配式活动房屋应当具有产品合格证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_77"},{"id":78,"type":"judge","stem":"建设单位对因建设工程施工可能造成损害的毗邻建筑物、构筑物和地下管线等，应当采取专项防护措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_78"},{"id":79,"type":"judge","stem":"在城市市区内的建设工程，施工单位应当对施工现场实行封闭围挡。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_79"},{"id":80,"type":"judge","stem":"生产经营单位安监部负责组织编制和实施本单位的应急预案，并对应急预案的真实性和实用性负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_80"},{"id":81,"type":"judge","stem":"综合应急预案，是指生产经营单位为应对各种生产安全事故而制定的综合性工作方案，是本单位应对生产安全事故的总体工作程序、措施和应急预案体系的总纲。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_81"},{"id":82,"type":"judge","stem":"专项应急预案，是指生产经营单位为应对某一种或者多种类型生产安全事故，或者针对重要生产设施、重大危险源、重大活动防止生产安全事故而制定的专项性工作方案。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_82"},{"id":83,"type":"judge","stem":"现场处置方案是指生产经营单位根据同一类型生产安全事故，相同场所、装置或者设施所制定的应急处置措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_83"},{"id":84,"type":"judge","stem":"编制应急预案前，编制单位应当进行事故风险辨识、评估和应急资源调查。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_84"},{"id":85,"type":"judge","stem":"作业人员进入新的岗位或者新的施工现场前，应当接受安全生产教育培训。未经教育培训或者教育培训考核不合格的人员，不得上岗作业。    （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_85"},{"id":86,"type":"judge","stem":"对于危险性较大的场所、装置或者设施，生产经营单位应当编制现场处置方案。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_86"},{"id":87,"type":"judge","stem":"事故风险单一、危险性小的生产经营单位，可以只编制综合应急预案。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_87"},{"id":88,"type":"judge","stem":"地方各级人民政府其他负有安全生产监督管理职责的部门的应急预案，应当抄送上一级人民政府应急管理部门。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_88"},{"id":89,"type":"judge","stem":"生产经营单位应当组织开展本单位的应急预案、应急知识、自救互救和避险逃生技能的培训活动，使有关人员了解应急预案内容，熟悉应急职责、应急处置程序和措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_89"},{"id":90,"type":"judge","stem":"生产经营单位未按照规定开展应急预案评审的，由县级以上人民政府应急管理部门责令限期改正，可以处1万元以上3万元以下的罚款。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_90"},{"id":91,"type":"judge","stem":"实行工程总承包的，总承包单位依法将建筑工程分包给其他单位的，总承包单位与分包单位应当在分包合同中明确安全防护、文明施工措施费用由总承包单位统一管理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_91"},{"id":92,"type":"judge","stem":"监理单位发现施工单位未落实施工组织设计及专项施工方案中安全防护和文明施工措施的，有权责令其立即整改。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_92"},{"id":93,"type":"judge","stem":"建设单位应当按照规定及合同约定及时向分包单位支付安全防护、文明施工措施费用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_93"},{"id":94,"type":"judge","stem":"国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的单位和个人，给予奖励。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_94"},{"id":95,"type":"judge","stem":"建设行政主管部门的工作人员发现违法行为不予查处的，由其所在单位或者上级主管机关给予行政处分。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_95"},{"id":96,"type":"judge","stem":"建设单位未按规定支付安全防护、文明施工措施费用，逾期仍未改正的，建设行政主管部门责令该建设工程停止施工。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_96"},{"id":97,"type":"judge","stem":"自购建筑起重机械的使用单位在建筑起重机械首次安装前，无需办理任何手续即可安装使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_97"},{"id":98,"type":"judge","stem":"建筑起重机械使用单位和安装单位应当在签订的建筑起重安装、拆卸合同中明确双方的安全生产责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_98"},{"id":99,"type":"judge","stem":"建筑起重机械安装单位仅需要按照建筑起重机械安装、拆卸工程专项施工方案组织施工安装、拆卸作业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_99"},{"id":100,"type":"judge","stem":"使用单位应当自建筑起重机械安装验收合格之日起15日内，向工程所在地县级以上人民政府建设主管部门办理建筑起重机械使用登记。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_100"},{"id":101,"type":"judge","stem":"建筑起重机械经安装单位自检合格后，即可投入使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_101"},{"id":102,"type":"judge","stem":"禁止擅自在建筑起重机械上安装非原制造厂制造的标准节和附着装置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_102"},{"id":103,"type":"judge","stem":"建筑起重机械出现故障或发生异常情况的，应立即停止使用，消除故障或事故隐患后，方可重新投入使用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_103"},{"id":104,"type":"judge","stem":"建筑起重机械在使用过程中需要附着或顶升的，使用单位应当委托原安装单位或者具有相应资质的安装单位按照专项方案实施，完成后即可使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_104"},{"id":105,"type":"judge","stem":"实行施工总承包的建设项目，建筑起重机械安装完毕后，由施工总承包单位组织验收。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_105"},{"id":106,"type":"judge","stem":"负责办理建筑起重机械备案或者登记的建设主管部门应当建立本行政区域内的建筑起重机械档案，按照有关规定对建筑起重机械进行统一编号，可以不向社会公布建筑起重机械的安全状况。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_106"},{"id":107,"type":"judge","stem":"建筑起重机械的使用登记标志，应当置于该设备的显著位置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_107"},{"id":108,"type":"judge","stem":"施工现场有多台塔式起重机作业时，可以不制定防止塔式起重机相互碰撞的安全措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_108"},{"id":109,"type":"judge","stem":"没有齐全有效的安全保护装置的建筑起重机械，可以投入使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_109"},{"id":110,"type":"judge","stem":"建筑施工企业提交了安全生产许可证申请，就可以从事建筑施工活动。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_110"},{"id":111,"type":"judge","stem":"建筑施工企业申请安全生产许可证，应当对申请材料实质性内容的真实性负责，不得隐瞒有关情况。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_111"},{"id":112,"type":"judge","stem":"建筑施工企业提交的安全生产许可证申请，经审查不符合安全生产条件的，不予颁发安全生产许可证，不需要通知企业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_112"},{"id":113,"type":"judge","stem":"建筑施工企业破产、倒闭、撤销的，无需办理安全生产许可证注销。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_113"},{"id":114,"type":"judge","stem":"建筑施工企业取得安全生产许可证后，不得降低安全生产条件。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_114"},{"id":115,"type":"judge","stem":"建筑施工企业在安全生产许可证有效期内，严格遵守有关安全生产的法律法规，未发生死亡事故的，安全生产许可证有效期届满时，经原安全生产许可证颁发管理机关同意，不再审查，安全生产许可证有效期延期2年。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_115"},{"id":116,"type":"judge","stem":"建设主管部门工作人员在安全生产许可证颁发、管理和监督检查工作中，不得索取或者接受建筑施工企业的财物，不得谋取其他利益。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_116"},{"id":117,"type":"judge","stem":"安全生产许可证颁发管理机关发现企业不再具备安全生产条件的，应当直接吊销安全生产许可证。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_117"},{"id":118,"type":"judge","stem":"建筑施工企业可以转让但不得冒用安全生产许可证或者使用伪造的安全生产许可证。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_118"},{"id":119,"type":"judge","stem":"暂扣、吊销安全生产许可证的行政处罚，由安全生产许可证的颁发管理机关决定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_119"},{"id":120,"type":"judge","stem":"任何单位和个人不得对依法实施的分包活动进行干预。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_120"},{"id":121,"type":"judge","stem":"建筑施工总承包企业可以将建设工程分包给个人。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_121"},{"id":122,"type":"judge","stem":"专业分包工程承包人可以和其他企业合作完成所承包的工程。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_122"},{"id":123,"type":"judge","stem":"依据《房屋建筑和市政基础设施工程施工分包管理办法》，分包工程发包人应当设立项目管理机构，组织管理所承包工程的施工活动。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_123"},{"id":124,"type":"judge","stem":"禁止将承包的工程进行转包。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_124"},{"id":125,"type":"judge","stem":"对安全培训机构的考核发证，可以收取一定的费用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_125"},{"id":126,"type":"judge","stem":"安全培训机构资质证书不得出租、出借给其他机构和个人。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_126"},{"id":127,"type":"judge","stem":"建筑施工企业应当建立健全企业安全生产教育培训制度，加强对职工安全生产的教育培训；但因客观条件限制未经安全生产教育培训的人员，也可以上岗作业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_127"},{"id":128,"type":"judge","stem":"安全培训机构从事安全培训工作可以根据市场随意收费。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_128"},{"id":129,"type":"judge","stem":"任何单位或者个人对安全培训机构的违法违纪行为，均有权向安全生产监督管理部门、煤矿安全监察机构报告或者举报。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_129"},{"id":130,"type":"judge","stem":"生产经营单位委托其他机构进行安全培训，保证安全培训的责任由其他机构负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_130"},{"id":131,"type":"judge","stem":"生产经营单位安排从业人员进行安全培训期间，可以不支付工资和必要的费用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_131"},{"id":132,"type":"judge","stem":"安全生产监督检查部门检查中发现安全生产教育培训落实不到位，有关人员未经培训合格的，应当视为生产安全事故隐患，责令限期整改。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_132"},{"id":133,"type":"judge","stem":"上一级安全培训机构可以承担下一级安全培训机构的培训工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_133"},{"id":134,"type":"judge","stem":"生产经营单位对承包、承租单位的事故隐患排查治理工作负有组织管理的职责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_134"},{"id":135,"type":"judge","stem":"负有安全监督管理职能的部门对生产经营单位事故隐患排查治理情况进行监督检查时，单位应积极配合，不得拒绝和阻挠。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_135"},{"id":136,"type":"judge","stem":"对不具备安全生产条件的生产经营单位，可以按照规定权限予以关闭。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_136"},{"id":137,"type":"judge","stem":"生产经营单位应当保证事故隐患排查治理所需资金，可不建立资金使用专项制度。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_137"},{"id":138,"type":"judge","stem":"县级以上安全监察监管部门在各自的职责范围内对安全生产违法行为行政处罚行使管辖区。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_138"},{"id":139,"type":"judge","stem":"生产经营单位对安全监察监管部门的行政处罚不服的，有权依法申请行政复议。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_139"},{"id":140,"type":"judge","stem":"有关人员因违法给与行政处罚受到损害的，不得申请赔偿。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_140"},{"id":141,"type":"judge","stem":"给予关闭的行政处罚，由县级以上安全监察部门决定。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_141"},{"id":142,"type":"judge","stem":"两个以上安全监管部门因行政处罚管辖权发生争议的，由其共同的上一级安全监管部门指定管辖。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_142"},{"id":143,"type":"judge","stem":"生产经营单位对安全监察监管部门停工、停产指令应当依法执行，及时消除事故隐患。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_143"},{"id":144,"type":"judge","stem":"生产经营单位对重大安全隐患拒不整改，有发生生产安全事故危险的，安全监管检查部门应当采取通知有关单位停电、停水的措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_144"},{"id":145,"type":"judge","stem":"按照国务院规定的权限和程序批准开工报告的建筑工程，不再领取施工许可证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_145"},{"id":146,"type":"judge","stem":"建筑工程未取得施工许可证的，一律不得开工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_146"},{"id":147,"type":"judge","stem":"建筑工程在施工过程中，建设单位或者施工单位发生变更的，应当重新申请领取施工许可证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_147"},{"id":148,"type":"judge","stem":"在建的建筑工程因故中止施工的，建设单位应当自中止施工之日起15天内向发证机关报告（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_148"},{"id":149,"type":"judge","stem":"建设工程因故中止施工满1年的，工程恢复施工前，建设单位应当报发证机关核验施工许可证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_149"},{"id":150,"type":"judge","stem":"建设项目安全设施的施工应当由取得相应资质的施工单位进行，在建设项目主体工程完工后施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_150"},{"id":151,"type":"judge","stem":"施工单位发现安全设施存在重大事故隐患时，应当立即停止施工并报告生产经营单位进行整改。整改合格后，方可恢复施工。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_151"},{"id":152,"type":"judge","stem":"施工单位应当严格按照安全设施设计和相关施工技术标准、规范施工，并对安全设施的施工安全负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_152"},{"id":153,"type":"judge","stem":"建设项目安全设施建成后，即可投入使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_153"},{"id":154,"type":"judge","stem":"应急预案编制单位应当建立应急预案定期评估制度，对预案内容的针对性和实用性进行分析，并对应急预案是否需要修订作出结论。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_154"},{"id":155,"type":"judge","stem":"对于某一种或者多种类型的事故风险,生产经营单位可以编制相应的专项应急预案,应当将专项应急预案并入综合应急预案。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_155"},{"id":156,"type":"judge","stem":"对于危险性较大的场所、装置或者设施,生产经营单位可以编制现场处置方案。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_156"},{"id":157,"type":"judge","stem":"事故风险单一、危险性小的生产经营单位,可以只编制现场处置方案。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_157"},{"id":158,"type":"judge","stem":"生产经营单位编制的各类应急预案之间可以相互衔接，也可以各自独立。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_158"},{"id":159,"type":"judge","stem":"已经进行应急预案备案的生产经营单位,在申请安全生产许可证时,可不提供相应的应急预案,仅提供应急预案备案登记表。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_159"},{"id":160,"type":"judge","stem":"矿山、金属冶炼、建筑施工等生产经营单位的应急救援预案应当每三年进行一次预案评估。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_160"},{"id":161,"type":"judge","stem":"“安管人员”安全生产考核可以收取费用","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_161"},{"id":162,"type":"judge","stem":"“安管人员”安全生产考核合格证书式样由各省建设主管部门统一规定。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_162"},{"id":163,"type":"judge","stem":"“安管人员”不得涂改、倒卖、出租、出借或者以其他形式非法转让安全生产考核合格证书。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_163"},{"id":164,"type":"judge","stem":"“安管人员”经建设主管部门考核合格，取得安全生产考核合格证，企业无需在进行培训和考核。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_164"},{"id":165,"type":"judge","stem":"工程项目实行总承包的，总承包企业项目负责人应当定期考核分包企业安全生产管理情况。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_165"},{"id":166,"type":"judge","stem":"项目专职安全生产管理人员应当每天在施工现场开展安全检查，安排他人监督危险性较大的分部分项工程安全专项施工方案实施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_166"},{"id":167,"type":"judge","stem":"项目专职安全生产管理人员应当每天在施工现场开展安全检查，对检查中发现的安全事故隐患，应当立即处理；不能处理的，应当及时报告项目负责人和企业安全生产管理机构。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_167"},{"id":168,"type":"judge","stem":"建筑施工企业主要负责人、项目负责人和专职安全生产管理人员未按规定履行安全生产管理职责，导致发生较大及以上生产安全事故的，考核机关可以撤销其安全生产考核合格证书。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_168"},{"id":169,"type":"judge","stem":"建筑施工企业专职安全生产管理人员未按规定履行安全生产管理职责，导致发生一般生产安全事故的，考核机关应当暂扣其安全生产考核合格证书六个月以上一年以下。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_169"},{"id":170,"type":"judge","stem":"机械类专职安全生产管理人员可以从事除起重机械、土石方机械以外的全部安全生产管理工作。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_170"},{"id":171,"type":"judge","stem":"土建类专职安全生产管理人员的代码为C1。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_171"},{"id":172,"type":"judge","stem":"国务院安全检查监督部门负责全国危大工程安全管理的指导监督。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_172"},{"id":173,"type":"judge","stem":"危大工程实行分包并由分包单位编制专项施工方案的，专项施工方案应当由总承包单位技术负责人及分包单位技术负责人共同审核签字并加盖单位公章。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_173"},{"id":174,"type":"judge","stem":"超过一定规模危险性较大分部分项工程专项施工方案经论证需修改后通过的，施工单位修改后即可组织施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_174"},{"id":175,"type":"judge","stem":"施工单位应当严格按照专项施工方案组织施工，可以根据施工实际对专项施工方案进行简单修改。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_175"},{"id":176,"type":"judge","stem":"因规划调整、设计变更等原因需修改专项施工方案的，修改后的专项施工方案应当按照规定重新审核和论证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_176"},{"id":177,"type":"judge","stem":"危大工程验收合格后，施工单位可以在施工现场明显位置设置验收标识牌，公示验收时间及责任人员。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_177"},{"id":178,"type":"judge","stem":"危大工程发生险情或者事故时，施工单位应当立即采取应急处置措施，并报告建设单位，由建设单位确定是否报告主管部门。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_178"},{"id":179,"type":"judge","stem":"县级以上地方人民政府住房城乡建设主管部门或者所属施工安全监督机构，在监督抽查中发现危大工程存在一般安全隐患的，应当责令停止施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_179"},{"id":180,"type":"judge","stem":"采用新技术、新工艺、新材料、新设备可能影响工程施工安全，尚无国家、行业及地方技术标准的分部分项工程属于危大工程范畴。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_180"},{"id":181,"type":"judge","stem":"建设项目涉及危大工程，建设单位应当依法提供真实、准确、完整的工程地质、水文地质和工程周边环境等资料。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_181"},{"id":182,"type":"judge","stem":"危大工程应急抢险结束后，施工单位应当组织勘察、设计、施工、监理等单位制定工程恢复方案，并对应急抢险工作进行后评估。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_182"},{"id":183,"type":"judge","stem":"危大工程专项方案专家论证前应当通过施工单位审核和总监理工程师审查。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_183"},{"id":184,"type":"judge","stem":"超过一定规模危险性较大分部分项工程专项施工方案专家论证结论为“通过”的，施工单位可参考专家意见自行修改完善，无需重新履行审批手续。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_184"},{"id":185,"type":"judge","stem":"危险性较大的分部分项工程施工时，应当安排专职安全生产管理人员现场监督。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_185"},{"id":186,"type":"judge","stem":"超过一定规模危险性较大分布分项工程专家论证，只要是专家库里的成员，均可以专家身份参加专家论证会。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_186"},{"id":187,"type":"judge","stem":"施工单位的主要负责人、项目负责人、专职安全生产管理人员应当经建设行政主管部门或者其他有关部门考核合格后方可任职。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_187"},{"id":188,"type":"judge","stem":"作业人员进入新的岗位或者新的施工现场前，应当接受安全生产教育培训。未经教育培训或者教育培训考核不合格的人员，不得上岗作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_188"},{"id":189,"type":"judge","stem":"安全生产许可证的有效期为2年。安全生产许可证有效期满需要延期的，企业应当于期满前6个月向原安全生产许可证颁发管理机关办理延期手续。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_189"},{"id":190,"type":"judge","stem":"安全培训机构的教师接受专门的培训后就可上岗。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_190"},{"id":191,"type":"judge","stem":"专职安全生产管理人员对违章指挥、违章操作的，应当立即报告，但无权制止。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_191"},{"id":192,"type":"judge","stem":"新申请专职安全生产管理人员安全生产考核只可以在机械、土建、综合三类中选择一类。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_192"},{"id":193,"type":"judge","stem":"建筑施工企业应当建立安全生产教育培训制度，制定年度培训计划，每2年对“安管人员”进行培训和考核，考核不合格的，不得上岗。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_193"},{"id":194,"type":"judge","stem":"主要负责人应当与项目负责人签订安全生产责任书，确定项目经济考核目标、奖惩措施，以及企业为项目提供的安全管理和技术保障措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_194"},{"id":195,"type":"judge","stem":"建筑工程、装修工程按照工程总造价配备项目专职安全生产管理人员数量。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_195"},{"id":196,"type":"judge","stem":"在中华人民共和国领域内从事生产经营活动的单位（以下统称生产经营单位）的安全生产，均适用《中华人民共和国安全生产法》。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_196"},{"id":197,"type":"judge","stem":"除适用《中华人民共和国安全生产法》外，有关法律、行政法规对消防安全和道路交通安全、铁路交通安全、水上交通安全、民用航空安全以及核与辐射安全、特种设备安全另有规定的，适用其规定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_197"},{"id":198,"type":"judge","stem":"负有安全生产监督管理职责的部门应当相互配合、齐抓共管、信息共享、资源共用，依法加强安全生产监督管理工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_198"},{"id":199,"type":"judge","stem":"生产单位制订本企业标准时可以宽松于国家标准或者行业标准。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_199"},{"id":200,"type":"judge","stem":"生产经营单位委托依法设立的为安全生产提供技术、管理服务的机构提供安全生产技术、管理服务的，保证安全生产的责任仍由生产经营单位负责。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_200"},{"id":201,"type":"judge","stem":"生产经营单位应当具备《中华人民共和国安全生产法》和有关法律、行政法规和国家标准或者行业标准规定的安全生产条件；不具备安全生产条件的，不得从事生产经营活动。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_201"},{"id":202,"type":"judge","stem":"矿山、金属冶炼、建筑施工、运输单位和危险物品的生产、经营、储存、装卸单位，应当设置安全生产管理机构或者配备专职安全生产管理人员。除前款规定以外的其他生产经营单位，从业人员超过一百人的，应当设置安全生产管理机构或者配备专职安全生产管理人员；从业人员在一百人以下的，应当配备专职或者兼职的安全生产管理人员从业人员，如在五十人以下，根据生产实际情况可以不配备安全生产管理人员。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_202"},{"id":203,"type":"judge","stem":"一个企业的特种作业人员的范围是由本企业安全管理部、企业工会连同生产管理部门根据企业生产特性研讨确定。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_203"},{"id":204,"type":"judge","stem":"生产经营单位的特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格，方可上岗作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_204"},{"id":205,"type":"judge","stem":"生产经营单位必须对安全设备进行经常性维护、保养，并定期检测，保证正常运转。维护、保养、检测应当作好记录，并由有关人员签字。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_205"},{"id":206,"type":"judge","stem":"生产经营单位可以根据生产环境变化的要求，关闭直接关系生产安全的监控、报警、防护、救生设备、设施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_206"},{"id":207,"type":"judge","stem":"生产经营单位应当建立健全并落实生产安全事故隐患排查治理制度，采取技术、管理措施，及时发现并消除事故隐患。事故隐患排查治理情况应当如实记录，并通过职工大会或者职工代表大会、信息公示栏等方式向从业人员通报。其中，重大事故隐患排查治理情况应当及时向负有安全生产监督管理职责的部门和职工大会或者职工代表大会报告。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_207"},{"id":208,"type":"judge","stem":"生产、经营、储存、使用危险物品的车间、商店、仓库经企业生产管理部门申请，企业工会组织同意后方可与员工宿舍在同一座建筑物内，只要员工宿舍设有符合紧急疏散要求、标志明显、保持畅通的出口、疏散通道即可。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_208"},{"id":209,"type":"judge","stem":"生产经营单位应当关注从业人员的身体、心理状况和行为习惯，加强对从业人员的心理疏导、精神慰藉，严格落实岗位安全生产责任，防范从业人员行为异常导致事故发生。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_209"},{"id":210,"type":"judge","stem":"生产经营单位应当教育和督促从业人员严格执行本单位的安全生产规章制度和安全操作规程；并向从业人员如实告知作业场所和工作岗位存在的危险因素、防范措施以及事故应急措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_210"},{"id":211,"type":"judge","stem":"生产经营单位的从业人员有权了解其作业场所和工作岗位存在的危险因素、防范措施及事故应急措施，但无权对本单位的安全生产工作提出建议，必须严格服从生产经营单位的统一安排。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_211"},{"id":212,"type":"judge","stem":"有关部门和机构应当对存在失信行为的生产经营单位及其有关从业人员采取加大执法检查频次、暂停项目审批、上调有关保险费率、行业或者职业禁入等联合惩戒措施，并向社会公示。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_212"},{"id":213,"type":"judge","stem":"负有安全生产监督管理职责的部门，根据生产经营情况可以要求被审查、验收的单位购买其指定的安全设备、器材或者其他产品，也可以在安全生产事项的审查、验收中收取合理的费用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_213"},{"id":214,"type":"judge","stem":"建设单位应当将拆除工程发包给具有相应资质等级的施工单位（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_214"},{"id":215,"type":"judge","stem":"禁止出租检测不合格的机械设备和施工机具及配件（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_215"},{"id":216,"type":"judge","stem":"在施工现场安装、拆卸施工起重机械和整体提升脚手架、模板等自升式架设设施，必须由专业的单位承担（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_216"},{"id":217,"type":"judge","stem":"安装、拆卸施工起重机械和整体提升脚手架、模板等自升式架设设施，应当编制拆装方案、制定安全施工措施，并由安全员现场监督（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_217"},{"id":218,"type":"judge","stem":"施工起重机械和整体提升脚手架、模板等自升式架设设施安装完毕后，安装单位应当自检，出具自检合格证明，并向施工单位进行安全使用说明，办理验收手续并签字（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_218"},{"id":219,"type":"judge","stem":"施工单位从事建设工程的新建、扩建、改建和拆除等活动，应在其资质等级许可的范围内承揽工程（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_219"},{"id":220,"type":"judge","stem":"施工单位的项目负责人应当由取得相应执业资格的人员担任，对建设工程项目的安全施工负责（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_220"},{"id":221,"type":"judge","stem":"施工单位应当设立安全生产管理机构，配备专职安全生产管理人员（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_221"},{"id":222,"type":"judge","stem":"总承包单位和分包单位对分包工程的安全生产各自承担责任（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_222"},{"id":223,"type":"judge","stem":"分包单位应当服从总承包单位的安全生产管理，分包单位不服从管理导致生产安全事故的，由分包单位承担全部责任（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_223"},{"id":224,"type":"judge","stem":"垂直运输机械作业人员、安装拆卸工、爆破作业人员、起重信号工、登高架设作业人员等特种作业人员，必须按照国家有关规定经过专门的安全作业培训，并取得特种作业操作资格证书后，方可上岗作业（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_224"},{"id":225,"type":"judge","stem":"施工单位应当在施工现场入口处、施工起重机械、出入通道口、楼梯口、孔洞口、桥梁口、等危险部位，设置明显的安全警示标志（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_225"},{"id":226,"type":"judge","stem":"施工单位应当向作业人员提供安全防护用具和安全防护服装，并书面告知危险岗位的操作规程和违章操作的危害（ ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_226"},{"id":227,"type":"judge","stem":"作业人员有权对施工现场的作业条件、作业程序和作业方式中存在的安全问题提出批评、检举和控告，有权拒绝违章指挥和强令冒险作业（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_227"},{"id":228,"type":"judge","stem":"在施工中发生危及人身安全的紧急情况时，作业人员有权立即停止作业或者在采取必要的应急措施后撤离危险区域（ ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_228"},{"id":229,"type":"judge","stem":"作业人员应当遵守安全施工的强制性标准、规章制度和操作规程，正确使用安全防护用具、机械设备等（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_229"},{"id":230,"type":"judge","stem":"施工单位的施工起重机械和整体提升脚手架、模板等自升式架设设施的登记标志应当置于或者附着于该设备的显著位置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_230"},{"id":231,"type":"judge","stem":"作业人员进入新的岗位或者新的施工现场前，应当接受安全生产教育培训（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_231"},{"id":232,"type":"judge","stem":"未经教育培训或者教育培训考核不合格的作业人员，可以上岗作业（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_232"},{"id":233,"type":"judge","stem":"意外伤害保险费由从业人员支付（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_233"},{"id":234,"type":"judge","stem":"安全生产许可证颁发管理机关应当自收到申请之日起45日内审查完毕，经审查符合本条例规定的安全生产条件的，颁发安全生产许可证 （   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_234"},{"id":235,"type":"judge","stem":"安全生产许可证颁发管理机关应当建立、健全安全生产许可证档案管理制度，可以不向社会公布企业取得安全生产许可证的情况（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_235"},{"id":236,"type":"judge","stem":"监察机关依照《中华人民共和国行政监察法》的规定，对安全生产许可证颁发管理机关及其工作人员履行本条例规定的职责实施监察（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_236"},{"id":237,"type":"judge","stem":"企业取得安全生产许可证后，不得降低安全生产条件，并应当加强日常安全生产管理，可以不接受安全生产许可证颁发管理机关的监督检查（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_237"},{"id":238,"type":"judge","stem":"建设单位、勘察单位、设计单位、施工单位、工程监理单位及其他与建设工程安全生产有关的单位，必须遵守安全生产法律、法规的规定，保证建设工程安全生产，依法承担建设工程安全生产责任（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_238"},{"id":239,"type":"judge","stem":"国家要求建设工程安全生产的科学技术研究和先进技术的推广应用，推进建设工程安全生产的科学管理（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_239"},{"id":240,"type":"judge","stem":"建设单位因建设工程需要，向有关部门或者单位查询前款规定的资料时，有关部门或者单位应当及时提供（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_240"},{"id":241,"type":"judge","stem":"勘察单位应当按照法律、法规和工程建设强制性标准进行勘察，提供的勘察文件应当真实、准确，满足建设工程安全生产的需要（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_241"},{"id":242,"type":"judge","stem":"工程监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设一般性标准（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_242"},{"id":243,"type":"judge","stem":"为建设工程提供机械设备和配件的单位，应当按照安全施工的要求配备齐全有效的保险、限位等安全设施和装置（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_243"},{"id":244,"type":"judge","stem":"专职安全生产管理人员负责对安全生产进行现场监督检查。发现安全事故隐患，应当及时向项目负责人和安全生产管理机构报告，并要求停止作业（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_244"},{"id":245,"type":"judge","stem":"施工现场临时搭建的建筑物应当符合安全使用要求，施工现场使用的装配式活动房屋应当具有产品合格证（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_245"},{"id":246,"type":"judge","stem":"施工单位应当遵守有关环境保护法律、法规的规定，在施工现场采取措施，防止或者减少粉尘、废气、废水、固体废物、噪声、振动和施工照明对人和环境的危害和污染（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_246"},{"id":247,"type":"judge","stem":"劳务单位应当向作业人员提供安全防护用具和安全防护服装，并书面告知危险岗位的操作规程和违章操作的危害（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_247"},{"id":248,"type":"judge","stem":"作业人员应当遵守安全施工的推荐性标准、规章制度和操作规程，正确使用安全防护用具、机械设备等（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_248"},{"id":249,"type":"judge","stem":"国务院负责安全生产监督管理的部门依照《中华人民共和国安全生产法》的规定，对全国建设工程安全生产工作实施综合监督管理（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_249"},{"id":250,"type":"judge","stem":"建设行政主管部门在审核发放施工许可证时，应当对建设工程是否有安全施工措施进行审查，对没有安全施工措施的，根据实际情况可颁发施工许可证（   ）。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_250"},{"id":251,"type":"judge","stem":"建设行政主管部门或者其他有关部门可以将施工现场的监督检查委托给建设工程安全监督机构具体实施（   ）。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_251"},{"id":252,"type":"judge","stem":"中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照工伤保险条例的规定享受工伤保险待遇的权利。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_252"},{"id":253,"type":"judge","stem":"根据《工伤保险条例》规定用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_253"},{"id":254,"type":"judge","stem":"职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_254"},{"id":255,"type":"judge","stem":"用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_255"},{"id":256,"type":"judge","stem":"工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_256"},{"id":257,"type":"judge","stem":"职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_257"},{"id":258,"type":"judge","stem":"社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_258"},{"id":259,"type":"judge","stem":"职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_259"},{"id":260,"type":"judge","stem":"张某在上班期间，由于上班前在家与妻子吵架心情不畅，为了报复妻子，故意造成断指伤残。张某因在上班期间造成的伤害，故应该认定其为工伤。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_260"},{"id":261,"type":"judge","stem":"工伤职工复诊治疗可按工伤病情由工伤职工自行决定进行复诊治疗。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_261"},{"id":262,"type":"judge","stem":"发生工伤事故后，第一时间必须先把工伤职工送进工伤指定医院进行治疗。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_262"},{"id":263,"type":"judge","stem":"劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_263"},{"id":264,"type":"judge","stem":"对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门需进行调查核实。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_264"},{"id":265,"type":"judge","stem":"社会保险行政部门工作人员与工伤认定申请人有利害关系的，根据情况考虑是否回避。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_265"},{"id":266,"type":"judge","stem":"在工作时间和工作岗位，突发疾病死亡或在72小时内经抢救无效死亡的，应视同工伤。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_266"},{"id":267,"type":"judge","stem":"职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_267"},{"id":268,"type":"judge","stem":"工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_268"},{"id":269,"type":"judge","stem":"工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_269"},{"id":270,"type":"judge","stem":"社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间停止支付工伤职工治疗工伤的医疗费用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_270"},{"id":271,"type":"judge","stem":"伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_271"},{"id":272,"type":"judge","stem":"建设工程实行施工总承包的，分包单位应当服从总承包单位的安全生产管理，分包单位不服从管理导致生产安全事故的，由分包单位承担主要责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_272"},{"id":273,"type":"judge","stem":"施工单位应当制定本单位生产安全事故应急救援预案，建立应急救援组织或者配备应急救援人员，配备必要的应急救援器材、设备，并定期组织演练。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_273"},{"id":274,"type":"judge","stem":"实行施工总承包的建设工程，由总承包单位负责上报事故。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_274"},{"id":275,"type":"judge","stem":"生产经营单位有生产安全事故应急救援预案、应急救援组织或者应急救援人员，配备必要的应急救援器材、设备。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_275"},{"id":276,"type":"judge","stem":"国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的单位和个人，给予奖励。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_276"},{"id":277,"type":"judge","stem":"从业人员发现事故隐患或者其他不安全因素，应当立即向现场安全生产管理人员或者本单位负责人报告；接到报告的人员应当及时予以处理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_277"},{"id":278,"type":"judge","stem":"核设施事故适用《生产安全事故报告和调查处理条例》。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_278"},{"id":279,"type":"judge","stem":"一般事故，是指造成3人以下死亡，或者10人以下重伤，或者1000万元以下直接经济损失的事故，其中的“以下”包括本数。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_279"},{"id":280,"type":"judge","stem":"事故发生后，事故现场有关人员应当立即向本单位负责人报告。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_280"},{"id":281,"type":"judge","stem":"情况紧急时，事故现场有关人员可以直接向事故发生地县级以上人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门报告。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_281"},{"id":282,"type":"judge","stem":"安全生产监督管理部门和负有安全生产监督管理职责的有关部门不可以越级上报事故情况。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_282"},{"id":283,"type":"judge","stem":"事故报告后出现新情况的，不用及时补报。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_283"},{"id":284,"type":"judge","stem":"事故发生后，有关单位和人员应当妥善保护事故现场以及相关证据。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_284"},{"id":285,"type":"judge","stem":"安全生产监督管理部门和负有安全生产监督管理职责的有关部门应当向社会公布备值班电话，受理事故报告和举报。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_285"},{"id":286,"type":"judge","stem":"上级人民政府认为必要时，可以调查由下级人民政府负责调查的事故。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_286"},{"id":287,"type":"judge","stem":"事故调查组有权向有关单位和个人了解与事故有关的情况，并要求其提供相关文件、资料，有关单位和个人不得拒绝。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_287"},{"id":288,"type":"judge","stem":"事故调查中需要进行技术鉴定的，事故调查组应当委托具有国家规定资质的单位进行技术鉴定，不可以直接组织专家进行技术鉴定。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_288"},{"id":289,"type":"judge","stem":"事故调查中需要进行技术鉴定的，技术鉴定所需时间不计入事故调查期限。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_289"},{"id":290,"type":"judge","stem":"事故调查组成员可随时发布有关事故的信息。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_290"},{"id":291,"type":"judge","stem":"事故调查报告报送负责事故调查的人民政府后，事故调查工作即告结束。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_291"},{"id":292,"type":"judge","stem":"应急救援队伍接到有关人民政府及其部门的救援命令或者签有应急救援协议的生产经营单位的救援请求后，应当立即参加生产安全事故应急救援。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_292"},{"id":293,"type":"judge","stem":"应急救援队伍根据救援命令参加生产安全事故应急救援所耗费用，不应由事故责任单位承担。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_293"},{"id":294,"type":"judge","stem":"参加生产安全事故现场应急救援的单位和个人可以不服从现场指挥部的统一指挥。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_294"},{"id":295,"type":"judge","stem":"现场指挥部或者统一指挥生产安全事故应急救援的人民政府及其有关部门应当完整、准确地记录应急救援的重要事项，妥善保存相关原始资料和证据。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_295"},{"id":296,"type":"judge","stem":"建设单位应当委托具有相应资质的工程质量检测单位进行建设工程安全检测，并签订书面合同。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_296"},{"id":297,"type":"judge","stem":"建设单位可适当明示或者暗示施工单位使用不合格的建筑材料、建筑构配件和设备。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_297"},{"id":298,"type":"judge","stem":"建设单位可以将建设工程中的一项检测业务拆分委托不同的检测单位。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_298"},{"id":299,"type":"judge","stem":"有特殊要求的建筑材料、专用设备、工艺生产线的建设工程，设计单位可以指定生产厂、供应商。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_299"},{"id":300,"type":"judge","stem":"施工单位项目负责人不得同时承担两个及两个以上的建设工程项目，可以委托他人代行职责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_300"},{"id":301,"type":"judge","stem":"建设工程总承包单位对承包的建设工程质量和安全生产负责；总承包单位将专业工程分包给其他单位的，总包单位对其分包工程的质量和安全生产负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_301"},{"id":302,"type":"judge","stem":"建设工程施工可能对毗邻建筑物、构筑物和地下管线等造成损害的，专业分包单位应当采取专项防护措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_302"},{"id":303,"type":"judge","stem":"施工作业人员有权对施工质量和安全生产问题提出批评、检举和控告，有权拒绝违章指挥和强令冒险作业，在发生危及人身安全的紧急情况时，有权立即停止作业或者在采取必要的应急措施后撤离危险区域。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_303"},{"id":304,"type":"judge","stem":"施工单位应当建立健全教育培训制度，仅需加强对作业人员的专业技能和安全生产培训，未经教育培训或者考核不合格的人员，不得上岗作业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_304"},{"id":305,"type":"judge","stem":"工程质量检测单位在对工程实体检测前，应当根据技术标准和工程实际，对委托检测内容制定检测方案，自行组织实施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_305"},{"id":306,"type":"judge","stem":"工程质量检测单位应当建立档案管理制度，对工程质量检测合同、委托单、原始记录和检测报告统一连续编号，发现异议及时修改。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_306"},{"id":307,"type":"judge","stem":"工程质量检测单位设立分支机构，不得违法转包检测业务，不得伪造数据出具虚假的检测报告，不得与其所检测工程的相关责任单位存在隶属关系或者其他利害关系。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_307"},{"id":308,"type":"judge","stem":"商品房在销售合同质量保证期限内出现工程质量缺陷，由建设单位承担保修责任和维修费用，建设单位可以依法向有关责任单位追偿。因用户使用不当影响房屋及其附属设施质量的，由用户承担维修费用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_308"},{"id":309,"type":"judge","stem":"建设工程质量安全监督机构发现有未履行基本建设程序而擅自开工的建设工程，应当责令立即停工，并依法处理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_309"},{"id":310,"type":"judge","stem":"国家机关工作人员在建设工程质量和安全生产监督管理工作中玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门依法给予行政处分；构成犯罪的，依法追究刑事责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_310"},{"id":311,"type":"judge","stem":"安全生产工作应当建立生产经营单位负责、群众参与、政府监管、行业自律、社会监督的机制。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_311"},{"id":312,"type":"judge","stem":"分管安全生产的负责人承担安全生产综合管理领导责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_312"},{"id":313,"type":"judge","stem":"县级以上人民政府实行领导干部安全生产责任制。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_313"},{"id":314,"type":"judge","stem":"生产经营单位应当按照国家有关规定，提取并使用安全生产费用，专门用于保障和改善安全生产条件，安全生产费用在成本中列支。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_314"},{"id":315,"type":"judge","stem":"所有行业领域的生产经营单位都要实施安全生产责任保险。（   ）","options":["A.错误","B.正确"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_315"},{"id":316,"type":"judge","stem":"矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位按照批准的安全设施设计施工，并对安全设施的工程质量负责。（   ）","options":["A.错误","B.正确"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_316"},{"id":317,"type":"judge","stem":"尾矿库闭库工作及闭库后的安全管理由应急管理部门提请县级以上人民政府指定管理单位负责。（   ）","options":["A.错误","B.正确"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_317"},{"id":318,"type":"judge","stem":"从业人员有权对本单位安全生产工作中存在的问题提出建议、批评、检举和控告。（   ）","options":["A.错误","B.正确"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_318"},{"id":319,"type":"judge","stem":"生产经营单位使用劳务派遣人员的，可以将安全生产保障责任转移给劳务派遣单位。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_319"},{"id":320,"type":"judge","stem":"县级应急管理部门可以委托乡（镇）人民政府、街道办事处负责安全生产的日常监督管理工作。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_320"},{"id":321,"type":"judge","stem":"新闻、出版、广播、电影、电视等单位有进行安全生产宣传教育的责任和义务。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_321"},{"id":322,"type":"judge","stem":"事故现场有关人员不得直接将事故报告给事故发生地县级应急管理部门和负有安全生产监督管理职责的有关部门。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_322"},{"id":323,"type":"judge","stem":"事故造成人员受伤和急性中毒的，医疗机构应当立即组织救治，医疗费用免费。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_323"},{"id":324,"type":"judge","stem":"上级人民政府可以提级调查由下级人民政府负责调查的事故。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_324"},{"id":325,"type":"judge","stem":"生产经营单位制定或者修改安全生产规章制度、作出有关安全生产的决定，应当听取工会的意见。（   ）","options":["A.错误","B.正确"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_325"},{"id":326,"type":"judge","stem":"《中华人民共和国安全生产法》制定的目的是为了加强安全生产工作，防止和减少生产安全事故，保障人民群众生命和财产安全，促进经济社会持续健康发展。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_326"},{"id":327,"type":"judge","stem":"工会依法对安全生产工作进行技术指导。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_327"},{"id":328,"type":"judge","stem":"生产经营单位的主要负责人应组织制订并实施本单位安全生产教育和培训计划。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_328"},{"id":329,"type":"judge","stem":"生产经营单位必须依法参加工伤保险，为从业人员缴纳保险费。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_329"},{"id":330,"type":"judge","stem":"生产经营单位的从业人员有依法获得安全生产保障的权利,并应当依法履行安全生产方面的义务。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_330"},{"id":331,"type":"judge","stem":"生产经营单位可以在从业人员自愿的情况下与其订立协议，免除或减轻其对从业人员因生产安全事故伤亡依法应承担的责任。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_331"},{"id":332,"type":"judge","stem":"发包单位将工程发包给不具有相应资质条件的承包单位的，或者违反《建筑法》规定将建筑工程肢解发包的，责令改正，处以罚款。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_332"},{"id":333,"type":"judge","stem":"特种设备安装、改造、修理竣工后，安装、改造、修理的施工单位应当在验收后30日内将相关技术资料和文件移交县级以上人民政府相关部门（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_333"},{"id":334,"type":"judge","stem":"《劳动法》规定的“职业安全卫生设施”是指安全技术方面的设施、劳动卫生方面的设施，但不包括生产性辅助设施 (如女工卫生室，更衣室，饮水设施等)。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_334"},{"id":335,"type":"judge","stem":"用人单位违章指挥，强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，但需要事先告知用人单位。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_335"},{"id":336,"type":"judge","stem":"劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_336"},{"id":337,"type":"judge","stem":"用人单位制定或者修改有关职业病防治的规章制度，应当听取工会组织的意见。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_337"},{"id":338,"type":"judge","stem":"用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_338"},{"id":339,"type":"judge","stem":"用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_339"},{"id":340,"type":"judge","stem":"省、自治区、直辖市人民政府对国家污染物排放标准中未作规定的项目，可以制定地方污染物排放标准；对国家污染物排放标准中已作规定的项目，可以制定严于国家污染物排放标准的地方污染物排放标准。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_340"},{"id":341,"type":"judge","stem":"企业事业单位和其他生产经营者，为改善环境，依照有关规定转产、搬迁、关闭的，人民政府应当予以支持。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_341"},{"id":342,"type":"judge","stem":"《环境保护法》中规定:“加强企业管理，实施文明施工，对于污染环境的废气、废水、废渣，要综合利用、化害为利:需要排放的，必须遵循国家规定的标准；一时达不到国家标准的要限制企业的生产规模，逾期达不到国家标准的要限期治理。”( )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_342"},{"id":343,"type":"judge","stem":"重大责任事故罪主体是一般主体，包括建筑企业的安全生产从业人员、安全生产管理人员以及对安全生产事故负有责任的包工头、无证从事生产、作业的人员等。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_343"},{"id":344,"type":"judge","stem":"谎报瞒报事故罪的客观方面是安全事故发生后，负有报告职责的人员不报或谎报事故情况，贻误事故抢救，并且具有严重情节的行为。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_344"},{"id":345,"type":"judge","stem":"在大中型公路桥梁和渡口周围两百米、公路隧道上方和洞口外一百米范围内，以及在公路两侧一定距离内，挖砂、采石、取土、倾倒废弃物的由交通主管部门责令停止违法行为，可以处三万元以下的罚款。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_345"},{"id":346,"type":"judge","stem":"根据《建设工程安全生产管理条例》，工程监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设强制性标准。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_346"},{"id":347,"type":"judge","stem":"设计单位应当考虑施工安全操作和防护的需要，对涉及施工安全的重点部位和环节在设计文件中注明,并对防范生产安全事故提出指导意见。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_347"},{"id":348,"type":"judge","stem":"施工现场临时搭建的建筑物应当符合安全使用要求。施工现场使用的装配式活动房屋应当具有安全许可证。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_348"},{"id":349,"type":"judge","stem":"发生生产安全事故后，施工单位应当采取措施防止事故扩大，保护事故现场。需要移动现场物品时，应当作出标记和书面记录，妥善保管有关证物。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_349"},{"id":350,"type":"judge","stem":"设计单位应当按照法律、法规和工程建设强制性标准进行设计，防止因设计不合理导致生产安全事故的发生。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_350"},{"id":351,"type":"judge","stem":"环境污染事故、核设施事故、国防科研生产事故的报告和调查处理不适用《生产安全事故报告和调查处理条例》。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_351"},{"id":352,"type":"judge","stem":"较大事故是指造成5人以上10人以下死亡,或者10人以上50人以下重伤,或者1000万元以上5000万元以下直接经济损失的事故。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_352"},{"id":353,"type":"judge","stem":"重大事故逐级上报至国务院安全生产监督管理部门和负有安全生产监督管理职责的有关部门。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_353"},{"id":354,"type":"judge","stem":"安全生产监督管理部门和负有安全生产监督管理职责的有关部门逐级上报事故情况，每级上报的时间不得超过24小时。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_354"},{"id":355,"type":"judge","stem":"较大事故由省级人民政府直接组织事故调查组或者授权或委托有关部门调查。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_355"},{"id":356,"type":"judge","stem":"施工单位对编制的专项施工方案必须组织专家进行论证、审查。( )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_356"},{"id":357,"type":"judge","stem":"不需要专家论证的危险性较大工程专项施工方案，经项目监理工程师审核通过、签字后，由施工单位项目经理批准实施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_357"},{"id":358,"type":"judge","stem":"已经批准的专项施工方案，不得随意改动，实施方案所需的安全技术措施经费不得挪作他用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_358"},{"id":359,"type":"judge","stem":"企业应当将安全费用优先用于满足安全生产监督管理部门对企业安全生产提出的整改措施或达到安全生产标准所需支出。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_359"},{"id":360,"type":"judge","stem":"企业为职工提供的职业病防治、工伤保险、医疗保险所需费用应在安全费用中列支。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_360"},{"id":361,"type":"judge","stem":"生产经营单位使用被派遣劳动者的，不必对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_361"},{"id":362,"type":"judge","stem":"生产经营单位应当建立安全生产教育和培训档案，如实记录安全生产教育和培训的时间、内容、参加人员以及考核结果等情况。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_362"},{"id":363,"type":"judge","stem":"生产经营单位可以短期将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_363"},{"id":364,"type":"judge","stem":"在风险管理的工作流程中，风险辨识是对各种风险衡量其风险量。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_364"},{"id":365,"type":"judge","stem":"节点和连接件出现破坏迹象是脚手架坍塌的早期征兆。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_365"},{"id":366,"type":"judge","stem":"公路桥梁和隧道工程施工安全风险等级分为Ⅰ级(低度风险)、Ⅱ级 (中度风险)、Ⅲ级(高度风险)、Ⅳ级(极高风险)。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_366"},{"id":367,"type":"judge","stem":"人机轨迹交又理论作为一种事故致因理论，强调人的因素在事故致因中的地位比物的因素更重要。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_367"},{"id":368,"type":"judge","stem":"生产经营单位待岗、转岗、换岗的从业人员，再重新上岗前，必须接受一次安全培训教育，时间不得少于20学时。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_368"},{"id":369,"type":"judge","stem":"对于各层次的管理者，除负责各自管理范围内的生产经营管理职责外，还应负责其运行范围内的安全生产管理，确保管理范围内的安全生产管理体系正常运行和安全业绩的持续改进。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_369"},{"id":370,"type":"judge","stem":"不具备安全生产教育培训条件的企业，不能委托具有相应资质的安全培训机构，对从业人员进行安全培训。 （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_370"},{"id":371,"type":"judge","stem":"企业应当建立健全内部安全费用管理制度，明确安全费用提取和使用的程序、职责及权限，按照规定提取和使用安全费用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_371"},{"id":372,"type":"judge","stem":"勘察单位应当对有可能引发公路水运工程安全隐患的地质灾害提出防治建议。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_372"},{"id":373,"type":"judge","stem":"生产经营单位不得以任何形式与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任，但从业人员有违章作业情形的除外。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_373"},{"id":374,"type":"judge","stem":"施工机械入场施工时，入场教育、安全技术交底等安全教育可以和施工同时进行。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_374"},{"id":375,"type":"judge","stem":"分包单位应当服从总承包单位的安全生产管理，分包单位不服从管理导致生产安全事故的，由分包单位承担全部责任。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_375"},{"id":376,"type":"judge","stem":"企业在安全生产许可证有效期内未发生死亡事故的，其安全生产许可证自动延期。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_376"},{"id":377,"type":"judge","stem":"较大事故是指造成5人以上10以下死亡,或者10人以上50以下重伤,或者1000万元以上5000万元以下直接经济损失的事故。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"law_判断_377"},{"id":378,"type":"judge","stem":"根据《安全色》规定，安全色分为红、黄、蓝、绿四种颜色，分别表示禁止、警告、指令和提示。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_378"},{"id":379,"type":"judge","stem":"用人单位使用未取得资格证书的人员从事建筑施工特种作业的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，处10万元以下罚款。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_379"},{"id":380,"type":"judge","stem":"项目专职安全生产管理人员在岗履职期间，应当佩戴安全生产检查记录仪，全过程视频记录在岗履职情况，任何人不得对视频资料进行编辑、篡改，原始视频资料至少留档保存6个月。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"law_判断_380"}]};